//! Standalone, opt-in characterization of the index at huge key counts.
//!
//! At P=3 (16.8M partitions) criterion is a poor fit: it reruns each benchmark for many samples,
//! and every insert sample would rebuild a multi-GB index. This binary instead builds each variant
//! once and reports insert, lookup, and batched (`get_many`) lookup ns/op. Keys are generated by a
//! seeded RNG rather than materialized (a 500M-key vector would be ~16 GB). The lookup phases
//! re-seed to replay the same keys, so the index itself is the only large allocation.
//!
//! Sizes are taken from numeric CLI args, e.g.
//! `cargo bench -p commonware-storage --bench index_scale -- 500000000`. With no args it runs the
//! default 20M/100M tier, but only when built with `--cfg huge_bench` -- so a bare `cargo bench`
//! (including CI's full-suite run) does nothing. Non-numeric args restrict which variants run by
//! name, e.g. `-- 1000000000 partitioned_ordered_3` runs only the SoA index at 1B (the heavy flat
//! baselines would need ~40+ GB at that size).
//!
//! A `batch=<size>[,<size>...]` arg sets the `get_many` batch sizes (default [DEFAULT_BATCHES]).
//! Each batch's keys are sorted before the call, as a caller iterating sorted keys passes them.

use commonware_runtime::{
    Metrics, Name, Supervisor,
    telemetry::metrics::{Metric, Registered},
};
use commonware_storage::{
    index::{Cursor as _, Unordered, ordered, partitioned, unordered},
    translator::{Cap, EightCap},
};
use commonware_utils::TestRng;
use rand::Rng;
use std::{
    hint::black_box,
    time::{Duration, Instant},
};

#[global_allocator]
static GLOBAL: commonware_allocator::mimalloc::MiMalloc =
    commonware_allocator::mimalloc::MiMalloc::new(commonware_allocator::mimalloc::Config::DEFAULT);

/// Keys per simulated batch in the apply phase, the updates per batch of the QMDB
/// `constantinople` bench.
const APPLY_BATCH: usize = 32_768;

/// How the apply phase warms a chunk's index entries before updating them.
#[derive(Clone, Copy, Debug)]
enum Probe {
    /// No probe.
    None,
    /// One `get` per key reading its first value, as `apply_batch` does, `chunk` keys at a time.
    Get(usize),
    /// One `get_many` per `chunk` keys.
    Many(usize),
}

impl Probe {
    fn parse(s: &str) -> Self {
        if s == "none" {
            return Self::None;
        }
        let chunk = |c: &str| c.parse().expect("probe chunk must be an integer");
        if let Some(c) = s.strip_prefix("get") {
            return Self::Get(chunk(c));
        }
        if let Some(c) = s.strip_prefix("many") {
            return Self::Many(chunk(c));
        }
        panic!("unknown probe {s:?}");
    }

    fn label(self) -> String {
        match self {
            Self::None => "none".into(),
            Self::Get(c) => format!("get{c}"),
            Self::Many(c) => format!("many{c}"),
        }
    }
}

/// Apply one sorted batch of `(key, current value)` updates as `apply_batch`'s fast path does: per
/// chunk, probe the chunk's keys, then find each key's current value and replace it (the index
/// half of `update_known_loc`).
fn apply_batch<I: Unordered<Value = u64>>(
    index: &mut I,
    batch: &[([u8; 8], u64)],
    probe: Probe,
    keys: &mut Vec<[u8; 8]>,
    offset: u64,
) {
    let chunk_len = match probe {
        Probe::None => batch.len(),
        Probe::Get(c) | Probe::Many(c) => c,
    };
    for chunk in batch.chunks(chunk_len) {
        let mut probed = 0u64;
        match probe {
            Probe::None => {}
            Probe::Get(_) => {
                for (key, _) in chunk {
                    probed ^= index.get(key).next().map_or(0, |value| *value);
                }
            }
            Probe::Many(_) => {
                keys.clear();
                keys.extend(chunk.iter().map(|(key, _)| *key));
                index.get_many(keys.as_slice(), |_, value| probed ^= *value);
            }
        }
        black_box(probed);
        for (key, old) in chunk {
            let mut cursor = index.get_mut(key).expect("key exists");
            assert!(cursor.find(|value| value == old));
            cursor.update(old + offset);
        }
    }
}

/// Insert `items` keys (timing the build), then time an `apply_batch`-like update phase for each
/// probe in `probes`: sorted batches of [APPLY_BATCH] existing keys, `per_run` keys per probe per
/// round, with the probe order rotating each round. Each run updates keys no earlier run touched,
/// so every run starts cold.
fn measure_apply<I: Unordered<Value = u64>>(
    mut index: I,
    items: u64,
    probes: &[Probe],
    rounds: usize,
    per_run: u64,
) -> (Duration, Vec<Duration>) {
    assert!(
        rounds as u64 * probes.len() as u64 * per_run <= items,
        "apply runs need more keys than the index holds"
    );
    let mut rng = TestRng::new(SEED);
    let start = Instant::now();
    for value in 0..items {
        index.insert(&rng.next_u64().to_be_bytes(), value);
    }
    let insert = start.elapsed();

    // Replay the insert sequence, so the next key's current value is its insertion index.
    let mut rng = TestRng::new(SEED);
    let mut next = 0u64;
    let mut applied = vec![Duration::ZERO; probes.len()];
    let mut batch = Vec::with_capacity(APPLY_BATCH);
    let mut keys = Vec::with_capacity(APPLY_BATCH);
    for round in 0..rounds {
        for i in 0..probes.len() {
            let p = (i + round) % probes.len();
            let mut remaining = per_run;
            while remaining > 0 {
                let n = remaining.min(APPLY_BATCH as u64);
                batch.clear();
                batch.extend((0..n).map(|_| {
                    next += 1;
                    (rng.next_u64().to_be_bytes(), next - 1)
                }));
                batch.sort_unstable();
                let start = Instant::now();
                apply_batch(&mut index, &batch, probes[p], &mut keys, items);
                applied[p] += start.elapsed();
                remaining -= n;
            }
        }
    }
    (insert, applied)
}

// Default no-arg tier: 20M keys gives ~1.2 entries per P=3 partition, 100M gives ~6 -- enough to
// exercise the per-partition sorted runs.
const DEFAULT_ITEMS: [u64; 2] = [20_000_000, 100_000_000];

// Default `get_many` batch sizes. 10,000 matches the updates per commit in the QMDB `scale`
// benchmark's `generate`, so it approximates the keys one merkleize probes.
const DEFAULT_BATCHES: [usize; 1] = [10_000];

// Fixed RNG seed so the insert and lookup phases generate the same key sequence.
const SEED: u64 = 0;

/// No-op metrics context. Mirrors the criterion benches' helper; duplicated because a separate
/// `harness = false` target cannot share the criterion entry point's module.
#[derive(Clone)]
struct DummyMetrics;

impl Supervisor for DummyMetrics {
    fn child(&self, _: &'static str) -> Self {
        Self
    }

    fn with_attribute(self, _: &'static str, _: impl std::fmt::Display) -> Self {
        Self
    }

    fn name(&self) -> Name {
        Name::default()
    }
}

impl Metrics for DummyMetrics {
    fn register<N: Into<String>, H: Into<String>, M: Metric>(
        &self,
        _: N,
        _: H,
        metric: M,
    ) -> Registered<M> {
        Registered::detached(metric)
    }

    fn encode(&self) -> String {
        String::new()
    }
}

/// Insert `items` keys (timing the build), look every key up one at a time (timing the gets), then
/// look every key up through `get_many` in sorted batches of each size in `batches` (timing only
/// the `get_many` calls), and return the timings with one `get_many` duration per batch size. Both
/// lookup phases read every value they find, as a caller would.
///
/// Keys come from a seeded RNG and are not stored, and each lookup phase re-seeds to replay the
/// identical sequence. A fast RNG keeps per-key generation negligible next to the index op, so the
/// numbers stay comparable to materialized keys.
fn measure<I: Unordered<Value = u64>>(
    mut index: I,
    items: u64,
    batches: &[usize],
) -> (Duration, Duration, Vec<Duration>) {
    let mut rng = TestRng::new(SEED);
    let start = Instant::now();
    for value in 0..items {
        index.insert(&rng.next_u64().to_be_bytes(), value);
    }
    let insert = start.elapsed();

    let mut rng = TestRng::new(SEED);
    let mut sum = 0u64;
    let start = Instant::now();
    for _ in 0..items {
        for value in index.get(&rng.next_u64().to_be_bytes()) {
            sum = sum.wrapping_add(*value);
        }
    }
    let lookup = start.elapsed();
    black_box(sum);

    let many = batches
        .iter()
        .map(|&batch| {
            let mut rng = TestRng::new(SEED);
            let mut keys = Vec::with_capacity(batch);
            let mut elapsed = Duration::ZERO;
            let mut remaining = items;
            while remaining > 0 {
                let n = remaining.min(batch as u64);
                keys.clear();
                keys.extend((0..n).map(|_| rng.next_u64().to_be_bytes()));
                keys.sort_unstable();
                let mut sum = 0u64;
                let start = Instant::now();
                index.get_many(&keys, |_, value| sum = sum.wrapping_add(*value));
                elapsed += start.elapsed();
                black_box(sum);
                remaining -= n;
            }
            elapsed
        })
        .collect();

    (insert, lookup, many)
}

fn main() {
    // Sizes come from numeric CLI args (e.g. `-- 500000000`). With none, use the default tier when
    // built with `--cfg huge_bench`; otherwise no-op, so a bare `cargo bench` (including CI's
    // full-suite run, which uses `--cfg full_bench`) does nothing.
    // Numeric args are sizes; other args name the variants to run (default: all). Flag-style args
    // (e.g. the `--bench` that `cargo bench` injects into the harness) are ignored.
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let args: Vec<u64> = argv.iter().filter_map(|a| a.parse().ok()).collect();
    let mut batches: Vec<usize> = argv
        .iter()
        .filter_map(|a| a.strip_prefix("batch="))
        .flat_map(|list| list.split(','))
        .map(|b| match b.parse() {
            Ok(batch) if batch > 0 => batch,
            _ => panic!("batch sizes must be positive integers, got {b:?}"),
        })
        .collect();
    if batches.is_empty() {
        batches = DEFAULT_BATCHES.to_vec();
    }
    let probes: Vec<Probe> = argv
        .iter()
        .filter_map(|a| a.strip_prefix("apply="))
        .flat_map(|list| list.split(','))
        .map(Probe::parse)
        .collect();
    let setting = |name: &str, default: u64| {
        argv.iter()
            .find_map(|a| a.strip_prefix(name))
            .map_or(default, |v| v.parse().expect("setting must be an integer"))
    };
    let rounds = setting("rounds=", 4) as usize;
    let per_run = setting("per_run=", 1 << 21);
    let only: Vec<String> = argv
        .into_iter()
        .filter(|a| a.parse::<u64>().is_err() && !a.starts_with('-') && !a.contains('='))
        .collect();
    let sizes = if !args.is_empty() {
        args
    } else if cfg!(huge_bench) {
        DEFAULT_ITEMS.to_vec()
    } else {
        eprintln!(
            "index_scale is opt-in; pass key counts (e.g. `-- 500000000`), or build with \
             `--cfg huge_bench` for the default 20M/100M tier"
        );
        return;
    };

    for items in sizes {
        println!("index_scale: items={items}");

        // Each variant is built once; insert is the timed build, lookup re-seeds and reuses the
        // populated index. P=3 ordered SoA (the structure under test) runs first, with byte-array
        // keys and then with the integer keys QMDB's P=3 ordered config uses. The flat BTree is
        // last because it is by far the slowest/heaviest baseline. (Ordered P=1/P=2 and unordered
        // P=3 are omitted: pathological build, or 16.8M hashmaps.)
        macro_rules! run {
            ($name:literal, $index:expr) => {{
                if (only.is_empty() || only.iter().any(|v| v.as_str() == $name))
                    && !probes.is_empty()
                {
                    let (insert, applied) = measure_apply($index, items, &probes, rounds, per_run);
                    print!(
                        "  {:<32} insert={} ns/op",
                        $name,
                        insert.as_nanos() / items as u128
                    );
                    let keys = (rounds as u64 * per_run) as f64;
                    for (probe, elapsed) in probes.iter().zip(applied) {
                        print!(
                            "  apply[{}]={:.1} ns/key",
                            probe.label(),
                            elapsed.as_nanos() as f64 / keys
                        );
                    }
                    println!();
                } else if only.is_empty() || only.iter().any(|v| v.as_str() == $name) {
                    let (insert, lookup, many) = measure($index, items, &batches);
                    print!(
                        "  {:<32} insert={} ns/op  lookup={} ns/op",
                        $name,
                        insert.as_nanos() / items as u128,
                        lookup.as_nanos() / items as u128,
                    );
                    for (batch, elapsed) in batches.iter().zip(many) {
                        print!(
                            "  get_many(batch={batch})={} ns/op",
                            elapsed.as_nanos() / items as u128
                        );
                    }
                    println!();
                }
            }};
        }

        run!(
            "partitioned_ordered_3",
            partitioned::ordered::Index::<_, _, 3>::new(DummyMetrics, Cap::<5>::new())
        );
        run!(
            "partitioned_ordered_3_eightcap",
            partitioned::ordered::Index::<_, _, 3>::new(DummyMetrics, EightCap)
        );
        run!("unordered", unordered::Index::new(DummyMetrics, EightCap));
        run!(
            "partitioned_unordered_1",
            partitioned::unordered::Index::<_, _, 1>::new(DummyMetrics, Cap::<7>::new())
        );
        run!(
            "partitioned_unordered_2",
            partitioned::unordered::Index::<_, _, 2>::new(DummyMetrics, Cap::<6>::new())
        );
        run!("ordered", ordered::Index::new(DummyMetrics, EightCap));
    }
}
